const I={chat:'<path d="M4 5h16v11H9l-5 4z"/>',ping:'<path d="M12 21s-6-5.6-6-11a6 6 0 0 1 12 0c0 5.4-6 11-6 11z"/><circle cx="12" cy="10" r="2"/>',move:'<path d="M4 12h13M13 6l6 6-6 6"/>',attackmove:'<circle cx="12" cy="12" r="7"/><path d="M12 2v5M12 17v5M2 12h5M17 12h5"/>',hold:'<path d="M12 3l7 3v5c0 5-3 8-7 10-4-2-7-5-7-10V6z"/>',all:'<circle cx="8" cy="8" r="3"/><circle cx="16" cy="8" r="3"/><path d="M2 20c1-4 3-6 6-6s5 2 6 6M10 20c1-4 3-6 6-6s5 2 6 6"/>',clear:'<path d="M6 6l12 12M18 6L6 18"/>',orbital:'<path d="M13 2L5 14h6l-2 8 8-12h-6z"/>',box:'<rect x="4" y="4" width="16" height="16" rx="2" stroke-dasharray="3 3"/><path d="M14 14l6 6"/>',build:'<path d="M14 4l6 6-3 3-6-6zM11 7l-8 8 3 3 8-8"/>',barricade:'<path d="M3 17h18M5 17l3-8h8l3 8M9 9v8M15 9v8"/>',watchtower:'<path d="M7 21l2-11h6l2 11M5 10h14M8 5h8l1 5H7z"/>',barracks:'<path d="M3 20V10l9-6 9 6v10zM9 20v-6h6v6"/>',workshop:'<path d="M3 20V9l9-5 9 5v11M7 20v-8h10v8M7 15h10"/>',clinic:'<path d="M9 3h6v6h6v6h-6v6H9v-6H3V9h6z"/>',rifle:'<circle cx="12" cy="6" r="3"/><path d="M6 21v-5a6 6 0 0112 0v5"/>',tank:'<path d="M3 15h18v4H3zM6 15v-4h9v4M15 12h6"/>',rocket:'<path d="M5 19l4-4M14 4l6 6-8 8-6-6zM17 3l4 4"/>',patrol:'<path d="M2 16V8h11v8M13 11h5l3 3v2h-8M6 19a2 2 0 100-4 2 2 0 000 4zM17 19a2 2 0 100-4 2 2 0 000 4z"/>',engineer:'<path d="M3 17h13l3-6h-6l-2-4H5zM6 20a2 2 0 100-4 2 2 0 000 4zM14 20a2 2 0 100-4 2 2 0 000 4z"/>',repair:'<path d="M14 6a4 4 0 005 5l-9 9-3-3 9-9a4 4 0 01-2-2z"/>',upgrade:'<path d="M6 14l6-6 6 6M6 20l6-6 6 6"/>',menu:'<path d="M5 7h14M5 12h14M5 17h14"/>',full:'<path d="M4 9V4h5M20 9V4h-5M4 15v5h5M20 15v5h-5"/>',help:'<circle cx="12" cy="12" r="9"/><path d="M9.5 9a2.5 2.5 0 015 .5c0 1.5-2.5 2-2.5 3.5M12 17h.01"/>',credits:'<circle cx="12" cy="12" r="8"/><path d="M12 7v10M9 9.5c0-1 1.3-1.5 3-1.5s3 .7 3 1.8-1.4 1.6-3 2-3 1-3 2.1 1.4 1.6 3 1.6 3-.6 3-1.5"/>',energy:'<path d="M13 2L5 14h6l-2 8 8-12h-6z"/>',supply:'<path d="M4 20v-2a4 4 0 014-4h8a4 4 0 014 4v2M12 11a4 4 0 100-8 4 4 0 000 8z"/>',timer:'<circle cx="12" cy="13" r="8"/><path d="M12 9v4l3 2M9 2h6"/>',intel:'<path d="M4 5h16v14H4zM8 9h8M8 13h5"/>',hq:'<path d="M4 21V8l8-5 8 5v13M9 21v-5h6v5M12 3v5"/>',warning:'<path d="M12 3l10 18H2zM12 10v5M12 18h.01"/>',play:'<path d="M7 4l13 8-13 8z"/>',flag:'<path d="M5 21V4M5 4h12l-2 4 2 4H5"/>',ied:'<path d="M4 15h16v5H4zM8 15v-3h8v3M12 12V8"/><path d="M12 8c0-3 3-3 3-5M17 2l1 1M19 4l1-1"/>',scanner:'<path d="M2 18h12l3-5h-5l-2-4H4z"/><path d="M15 3a7 7 0 017 7M15 6.5a3.5 3.5 0 013.5 3.5"/><circle cx="6" cy="19" r="1.6"/><circle cx="12" cy="19" r="1.6"/>',defuse:'<circle cx="11" cy="14" r="6"/><path d="M11 8V4M8 4h6M7 10l8 8M18 3l3 3M17 7l4-4"/>',sound:'<path d="M4 9h4l5-4v14l-5-4H4z"/><path d="M16 9a4 4 0 010 6M18.5 6.5a8 8 0 010 11"/>',mute:'<path d="M4 9h4l5-4v14l-5-4H4z"/><path d="M17 9l5 6M22 9l-5 6"/>'};
const svg=name=>'<svg viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">'+(I[name]||'')+'</svg>';
const $=s=>document.querySelector(s),escapeHTML=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v)),distance=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y),clock=s=>Math.floor(Math.max(0,s)/60)+':'+String(Math.floor(Math.max(0,s)%60)).padStart(2,'0');
let socket=null,game=null,me='',team=0,room='',isHost=false,connected=false,reconnectTimer=null,view='home',prevPhase=null,animation=null;
let selected=new Set(),action='context',zoom=1,camera={x:1200,y:675},pointer=null,dragBox=null,canvas=null,ctx=null,background=null,backgroundKey='',minimap=null,minictx=null,minimapBase=null,lastDraw=0,lastOverlay=0;
let lastStateAt=0,stallWarned=false;
// Watchdog: if live updates stop arriving, say so and reconnect instead of leaving a frozen battlefield.
setInterval(()=>{if(view!=='playing'||game?.phase!=='playing'||!connected||document.hidden)return;const quiet=performance.now()-lastStateAt;
 if(quiet>2500&&!stallWarned){stallWarned=true;document.body.classList.add('lagging');const n=$('#network-indicator');if(n)n.textContent='◌ SLOW LINK'}
 if(quiet<2500&&stallWarned){stallWarned=false;document.body.classList.remove('lagging');const n=$('#network-indicator');if(n)n.textContent='● CONNECTED'}
 if(quiet>7000){lastStateAt=performance.now();try{socket?.close()}catch{}}},1000);
let toastTimer=null,prefer3d=localStorage.getItem('iron-frontier-view')!=='2d';
let tutorialRequested=false,tutorial=null,guidanceDismissed=false,previousNodeOwners=[],lastOwnedCount=0,boxMode=false,lastTap={id:'',at:0};
let hudCache=new Map(),lastGuidanceKey='',selectedStructure='',placement=null,buildOpen=false,intro=null,alerts={wave:0,facilityHp:new Map(),lastAttack:0,pings:[]},deployTimer=null,launchIntent=null;
const app=$('#app');
// ---------- Campaign: Defend the North ----------
// Simplified Nigeria outline (lon, lat) for the campaign map; rivers give it a sense of place.
const NG_OUTLINE=[[2.7,6.37],[2.72,6.9],[2.75,7.9],[2.68,8.5],[3.05,9.08],[3.33,9.85],[3.6,10.3],[3.65,10.8],[3.57,11.3],[3.62,11.69],[3.65,12.5],[4.1,13.5],[4.9,13.75],[5.5,13.86],[6.4,13.6],[7,13],[7.8,13.35],[8.6,13],[9,12.8],[10,13.25],[11,13.35],[12,13.1],[12.6,13.3],[13.3,13.7],[14.08,13.08],[14.55,12.25],[14.2,11.6],[13.9,11],[13.65,10.6],[13.25,10.1],[13.2,9.1],[12.8,8.7],[12.2,7.9],[11.75,7],[11.1,6.45],[10.6,7.05],[9.8,6.1],[9.5,5.9],[8.85,4.9],[8.6,4.5],[8.3,4.55],[7.5,4.4],[6.5,4.3],[6,4.27],[5.6,4.6],[5.2,5.2],[4.6,6.15],[3.8,6.4],[3.4,6.42]];
const NG_RIVERS=[[[3.6,11.7],[4.1,11.2],[4.5,10.5],[4.8,9.6],[5.2,9],[6,8.6],[6.75,7.8],[6.75,6.9],[6.78,6.15],[6.6,5.3],[6.3,4.6]],[[13.2,9.3],[12.4,9.2],[11.5,8.9],[10.4,8.3],[9.3,7.8],[8.5,7.73],[7.6,7.75],[6.75,7.8]]];
const PIN_LABEL={abuja:[11,15,'start'],kaduna:[-11,4,'end'],jos:[11,5,'start'],kano:[-11,-5,'end'],damaturu:[0,23,'middle'],maiduguri:[4,-14,'middle']};
const ngPoint=(lon,lat)=>[+((lon-2.4)*30).toFixed(1),+((14.1-lat)*30).toFixed(1)],ngPath=points=>points.map((p,i)=>(i?'L':'M')+ngPoint(p[0],p[1]).join(' ')).join('');
const savedTheatre=()=>MAPS.theatre(localStorage.getItem('homestand-theatre')).id;
function campaign(){try{return JSON.parse(localStorage.getItem('homestand-campaign')||'{}')||{}}catch{return {}}}
function recordCampaign(id,stars){const progress=campaign();if(stars>(progress[id]||0)){progress[id]=stars;localStorage.setItem('homestand-campaign',JSON.stringify(progress))}}
const theatre=()=>game?.theatreId?MAPS.theatre(game.theatreId):null;
const iedRisk=v=>v>=.9?'Extreme':v>=.6?'High':v>=.45?'Elevated':'Low';
function theatreDetail(id){const t=MAPS.theatre(id),stars=campaign()[id]||0;
 return '<small>THEATRE '+t.order+' OF '+MAPS.theatreIds.length+' · '+escapeHTML(t.state.toUpperCase())+(t.state==='FCT'?'':' STATE')+'</small><h3>'+escapeHTML(t.operation)+'</h3><b class="theatre-place">'+svg('flag')+escapeHTML(t.city+' · '+t.area)+'</b><p>'+escapeHTML(t.briefing)+'</p>'
  +'<div class="threat-tags"><span class="tag">'+svg('warning')+'Assault ×'+t.threat.waves.toFixed(2).replace(/0$/,'')+'</span><span class="tag ied-'+iedRisk(t.threat.ied).toLowerCase()+'">'+svg('ied')+'IED risk: '+iedRisk(t.threat.ied)+'</span>'+(t.threat.sweepers?'<span class="tag">'+svg('scanner')+'Enemy sweepers</span>':'')+'</div>'
  +'<div class="theatre-stars" aria-label="'+stars+' of 3 stars">'+[0,1,2].map(i=>'<i class="'+(i<stars?'on':'')+'"></i>').join('')+'<span>'+(stars?'Secured':'Not yet secured')+'</span></div>'}
function campaignMarkup(side=''){const chosen=savedTheatre(),progress=campaign(),ids=MAPS.theatreIds,front=ids.map(id=>{const t=MAPS.theatre(id);return [t.lon,t.lat]}),[lx,ly]=ngPoint(3.38,6.45);
 return '<div class="campaign"><div class="ng-map"><svg viewBox="0 0 372 300" role="group" aria-label="Campaign map of Nigeria — choose a city to defend"><defs><radialGradient id="ng-glow" cx="70%" cy="20%" r="80%"><stop offset="0" stop-color="#2b4c4a"/><stop offset="1" stop-color="#11262b"/></radialGradient></defs>'
  +'<path class="ng-land" d="'+ngPath(NG_OUTLINE)+'Z"/>'+NG_RIVERS.map(r=>'<path class="ng-river" d="'+ngPath(r)+'"/>').join('')
  +'<path class="ng-front" d="'+ngPath(front)+'"/><g class="ng-ref"><circle cx="'+lx+'" cy="'+ly+'" r="2.4"/><text x="'+(lx+6)+'" y="'+(ly+3)+'">Lagos</text></g>'
  +ids.map(id=>{const t=MAPS.theatre(id),[x,y]=ngPoint(t.lon,t.lat),[dx,dy,anchor]=PIN_LABEL[id]||[11,4,'start'];return '<g class="ng-pin'+(id===chosen?' selected':'')+(progress[id]?' cleared':'')+'" data-theatre="'+id+'" tabindex="0" role="button" aria-pressed="'+(id===chosen)+'" aria-label="'+escapeHTML(t.city+', '+t.operation)+'"><circle class="pulse" cx="'+x+'" cy="'+y+'" r="12"/><circle class="dot" cx="'+x+'" cy="'+y+'" r="7.5"/><text class="num" x="'+x+'" y="'+(y+3.4)+'">'+t.order+'</text><text class="label" x="'+(x+dx)+'" y="'+(y+dy)+'" text-anchor="'+anchor+'">'+escapeHTML(t.city)+'</text></g>'}).join('')
  +'</svg></div><div class="campaign-side"><div id="theatre-detail" class="theatre-detail" aria-live="polite">'+theatreDetail(chosen)+'</div>'+side+'</div></div>'}
function chooseTheatre(id){localStorage.setItem('homestand-theatre',id);for(const pin of document.querySelectorAll('.ng-pin')){const on=pin.dataset.theatre===id;pin.classList.toggle('selected',on);pin.setAttribute('aria-pressed',String(on))}const detail=$('#theatre-detail');if(detail)detail.innerHTML=theatreDetail(id);const t=MAPS.theatre(id);hudText('#deploy-detail',t.city+' · 12–15 minutes');window.HomestandHome?.setTheatre?.(id)}
// ---------- Radio chatter ----------
let radioTimer=null,radioClock=0;
function radio(line,urgent=false){const el=$('#radio');if(!el||!line)return;el.querySelector('span').textContent=line;el.classList.toggle('urgent',urgent);el.hidden=false;el.classList.remove('show');void el.offsetWidth;el.classList.add('show');window.HomestandAudio?.play('radio');clearTimeout(radioTimer);radioTimer=setTimeout(()=>{if($('#radio'))$('#radio').hidden=true},5200)}

function toast(message){const element=$('#toast');element.textContent=message;element.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>element.classList.remove('visible'),2600)}
const send=payload=>{if(socket?.readyState!==WebSocket.OPEN){toast('Connecting to battle server…');return false}socket.send(JSON.stringify(payload));return true};
const sessionKey='iron-frontier-session',safeMission=()=>game?.missionId==='safe-haven';
// Territory War shares the construction HUD with Safe Haven; S() normalises structure data per mode and faction.
const CAT=window.HomestandCatalog,territoryMode=()=>game?.scenario==='territory',buildMode=()=>safeMission()||territoryMode();
const UNIT_COST={rifle:[60,1],tank:[165,3],rocket:[130,2],scanner:[110,2],patrol:[145,3],engineer:[120,2]};
function S(type){if(territoryMode()&&CAT){const d=CAT.STRUCTURES[type];return d?{...d,label:CAT.name(type,team),time:d.buildTime}:null}return STRUCTURES[type]}
const unitName=(type,t=team)=>territoryMode()&&CAT?CAT.UNIT_NAMES[t]?.[type]||type:(SAFE_CLASSES[type]?.label||(type==='patrol'?'Protected Patrol':type==='scanner'?'Eagle-Eye':type));
const factionName=t=>territoryMode()?(t===0?'Community Defence':'Raiders'):(t===0?'Azure Union':'Crimson Legion');
const frontierPlots=()=>MAPS.layouts.frontier?.plots||[];
function saveSession(){sessionStorage.setItem(sessionKey,JSON.stringify({code:room,id:me,team,name:localStorage.getItem('iron-frontier-name')||'Commander'}))}
function clearSession(){sessionStorage.removeItem(sessionKey)}
function connect(){if(socket&&socket.readyState===WebSocket.OPEN)return;const url=(location.protocol==='https:'?'wss':'ws')+'://'+location.host+'/ws';socket=new WebSocket(url);
 socket.onopen=()=>{connected=true;$('#network-indicator')?.replaceChildren(document.createTextNode('● CONNECTED'));document.body.classList.remove('offline');clearTimeout(reconnectTimer);const sess=JSON.parse(sessionStorage.getItem(sessionKey)||'null'),code=sess?.code||sess?.room;if(code&&sess?.id){send({type:'join',...sess,code});}};
 socket.onclose=()=>{connected=false;document.body.classList.add('offline');if($('#network-indicator'))$('#network-indicator').textContent='○ RECONNECTING';reconnectTimer=setTimeout(connect,1300)};
 socket.onerror=()=>{};
 let stateFrame=0;
 socket.onmessage=e=>{let data;try{data=JSON.parse(e.data)}catch{return}if(data.type==='joined'){room=data.code;me=data.id;team=data.team;saveSession();history.replaceState({},'',location.pathname+'?room='+room);return}
  if(data.type==='chat'){receiveChat(data);return}
  if(data.type==='ping'){receivePing(data);return}
  if(data.type==='notice'){toast(data.message);return}
  if(data.type==='error'){toast(data.message);hideDeploy();if(data.message.includes('expired')||data.message.includes('not found')){clearSession();room='';me='';game=null;renderHome()}return}
  if(data.type==='state'){const prev=game?.phase,previousRoster=(game?.participants||[]).map(player=>player.id+':'+player.connected).join('|');game=data;room=data.code;me=data.me;team=data.team;isHost=data.host;selected=new Set([...selected].filter(id=>game.units.some(u=>u.id===id&&u.team===team)));const rosterChanged=previousRoster!==(game.participants||[]).map(player=>player.id+':'+player.connected).join('|');
   if(data.phase!==prev||view!==data.phase||(data.phase==='lobby'&&rosterChanged)){if(data.phase==='playing')renderBattle();else if(data.phase==='results')renderResults();else renderLobby()}
   lastStateAt=performance.now();
   // Snapshots that arrive in a burst (after a network hiccup) are coalesced: only the newest is
   // drawn, once per frame, so a slow connection never queues up seconds of stale work.
   if(data.phase==='playing'){if(data.phase!==prev){updateHud();window.Iron3D?.sync(game,selected)}else if(!stateFrame)stateFrame=requestAnimationFrame(()=>{stateFrame=0;if(view==='playing'&&game?.phase==='playing'){updateHud();window.Iron3D?.sync(game,selected)}})}
  }
 };
}

// ---------- Deploy transition ----------
function showDeploy(title,detail,progress=.15){let el=$('#deploy-screen');if(!el){el=document.createElement('div');el.id='deploy-screen';el.className='deploy-screen';el.innerHTML='<img src="/assets/homestand-poster.jpg" alt=""><div class="deploy-copy"><small>DEPLOYING</small><strong></strong><span></span><i><b></b></i></div>';document.body.append(el)}el.querySelector('strong').textContent=title;el.querySelector('span').textContent=detail;el.querySelector('b').style.width=Math.round(progress*100)+'%';el.classList.remove('done');el.classList.add('visible');clearTimeout(deployTimer);deployTimer=setTimeout(hideDeploy,15000)}
function hideDeploy(){const el=$('#deploy-screen');if(!el)return;el.querySelector('b').style.width='100%';el.classList.add('done');clearTimeout(deployTimer);deployTimer=setTimeout(()=>el.classList.remove('visible','done'),420)}

