 const sheet=(id,open)=>{for(const s of ['#operations','#how-sheet'])$(s).hidden=s!==id||!open;document.querySelector('.home-stage').classList.toggle('sheet-open',Boolean(open));window.HomestandHome?.focus?.(open&&id==='#operations'?'battle':'tour')};
 $('#play-now').onclick=()=>returning()?sheet('#operations',true):begin('solo',{missionId:'safe-haven',training:true});
 $('#open-operations').onclick=()=>sheet('#operations',true);$('#ops-back').onclick=()=>sheet(null,false);$('#how-to-play').onclick=()=>sheet('#how-sheet',true);$('#how-back').onclick=()=>sheet(null,false);
 $('#play-friends').onclick=()=>{sheet('#operations',true);$('#friend-form').classList.remove('hidden');$('#roomField').focus({preventScroll:true})};
 $('#how-train').onclick=()=>begin('solo',{missionId:'safe-haven',training:true});$('#tutorial').onclick=()=>begin('solo',{missionId:'safe-haven',training:true});
 $('#safe-haven').onclick=()=>begin('solo',{missionId:'safe-haven'});$('#solo').onclick=()=>begin('solo');$('#friend').onclick=()=>$('#friend-form').classList.toggle('hidden');$('#host').onclick=()=>begin('pvp');
 for(const group of ['difficulty','battlefield','tw-faction','tw-prep','tw-difficulty'])for(const input of document.querySelectorAll('input[name="'+group+'"]'))input.onchange=()=>{for(const other of document.querySelectorAll('input[name="'+group+'"]'))other.closest('label')?.classList.toggle('selected',other.checked);if(group==='battlefield')localStorage.setItem('iron-frontier-map',input.value);if(group.startsWith('tw-'))localStorage.setItem('homestand-'+group,input.value)};
 const territory=(mode,coop=false)=>{const value=name=>document.querySelector('input[name="'+name+'"]:checked')?.value,faction=value('tw-faction')||'defence',prepMinutes=Number(value('tw-prep')||5),difficulty=value('tw-difficulty')||'recruit',t=MAPS.theatre(savedTheatre());localStorage.setItem('iron-frontier-name',commander());clearSession();tutorialRequested=false;launchIntent={territory:true};if(send({type:'create',mode,coop,scenario:'territory',faction,prepMinutes,difficulty,theatreId:t.id,name:commander()})){showDeploy('Territory War · '+t.city,mode==='pvp'||coop?'Creating a private room':'Deploying the '+(faction==='raiders'?'raider camp':'community defence HQ'),.2);PLATFORM?.emit('launch',{mode,scenario:'territory',faction,difficulty})}};
