  const produce=(id,type,icon)=>'<button id="'+id+'" data-produce="'+type+'"'+(type==='engineer'?' data-safe-build="engineer"':'')+' class="ctx-btn hidden">'+svg(icon)+'<span><b class="unit-name">'+escapeHTML(unitName(type))+'</b><small>'+UNIT_COST[type][0]+' CR · '+UNIT_COST[type][1]+' supply</small></span></button>';
